async def act(page):
    """
    From the current Manage Products grid state, apply the Name filter (Search), open the Frankie Sweatshirt edit page,
    run the create-configurations / associated products flow to add Color = Blue for Size S and Size M, then Save.

    All interactions use accessibility-role selectors and .select_option for <select> elements. The final action is
    a Save button click (which may navigate away) and thus is the last Playwright action in this function.
    """
    import asyncio

    # Helper: try clicking the first available control by role within a given scope
    async def try_click_any(scope, role, names):
        for n in names:
            try:
                await scope.get_by_role(role, name=n).click()
                return True
            except Exception:
                continue
        return False

    # 1) Close any blocking popup if present (try common close labels and Escape)
    await try_click_any(page, "button", ["×", "Close", "Close dialog", "Dismiss", "Cancel", "OK"])  
    try:
        await page.keyboard.press("Escape")
    except Exception:
        pass

    # 2) Click Search inside the "Reset Filter Search" cell to ensure the Name filter is applied
    try:
        reset_cell = page.get_by_role("cell", name="Reset Filter Search")
        await reset_cell.get_by_role("button", name="Search").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # fallback to top-level Search button
        try:
            await page.get_by_role("button", name="Search").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(1)

    # 3) Find the product row containing Frankie Sweatshirt and read the Edit link href
    product_href = None
    try:
        frankie_row = page.get_by_role("row").filter(has=page.get_by_role("cell", name="Frankie Sweatshirt"))
        edit_link = frankie_row.get_by_role("link", name="Edit")
        href = await edit_link.get_attribute("href")
        if href:
            product_href = href
    except Exception:
        product_href = None

    # 4) Fallback: direct link lookups
    if not product_href:
        try:
            l = page.get_by_role("link", name="Frankie Sweatshirt")
            href = await l.get_attribute("href")
            if href:
                product_href = href
        except Exception:
            product_href = None

    if not product_href:
        try:
            l = page.get_by_role("link", name="Frankie")
            href = await l.get_attribute("href")
            if href:
                product_href = href
        except Exception:
            product_href = None

    # 5) If we couldn't obtain an href, as a last resort click the product link (this will navigate away -> last action)
    if not product_href:
        try:
            await page.get_by_role("link", name="Frankie Sweatshirt").click()
            return
        except Exception:
            return

    # 6) Navigate to the product edit page using the href (use goto so we can continue interacting)
    await page.goto(product_href)
    await page.wait_for_load_state("networkidle")

    # 7) Close any popup on the edit page
    await try_click_any(page, "button", ["×", "Close", "Dismiss", "Cancel"]) 
    try:
        await page.keyboard.press("Escape")
    except Exception:
        pass

    # 8) Open the Associated / Configurations section (try typical labels and roles)
    assoc_labels = [
        "Associated Products",
        "Associated Products / Variations",
        "Associated",
        "Configurations",
        "Configurable Product Variations",
        "Associated Items",
        "Product Variations",
    ]
    assoc_opened = False
    for name in assoc_labels:
        try:
            await page.get_by_role("tab", name=name).click()
            assoc_opened = True
            break
        except Exception:
            try:
                await page.get_by_role("link", name=name).click()
                assoc_opened = True
                break
            except Exception:
                try:
                    await page.get_by_role("button", name=name).click()
                    assoc_opened = True
                    break
                except Exception:
                    continue
    if assoc_opened:
        await asyncio.sleep(0.7)

    # 9) Click Create Configurations / Create Products (try to scope to a group first)
    create_names = [
        "Create Configurations",
        "Create Configurations...",
        "Create Products",
        "Create Product",
        "Add Product",
        "Add New Product",
        "Create Variations",
    ]
    created = False
    for container_name in ["Associated Products", "Configurations", "Associated"]:
        try:
            container = page.get_by_role("group", name=container_name)
            for btn in create_names:
                try:
                    await container.get_by_role("button", name=btn).click()
                    created = True
                    break
                except Exception:
                    continue
            if created:
                break
        except Exception:
            continue

    if not created:
        for btn in create_names:
            try:
                await page.get_by_role("button", name=btn).click()
                created = True
                break
            except Exception:
                continue

    await asyncio.sleep(1)

    # 10) In the wizard: select attributes Color and Size (checkbox fallback)
    try:
        try:
            await page.get_by_role("checkbox", name="Color").check()
        except Exception:
            pass
        try:
            await page.get_by_role("checkbox", name="Size").check()
        except Exception:
            pass
    except Exception:
        pass

    # 11) Move to next step
    await try_click_any(page, "button", ["Next", "Continue", "Next Step", "Continue to Step 2"]) 
    await asyncio.sleep(0.7)

    # 12) Select Color = Blue and Size = S and M (combobox preferred, checkboxes fallback)
    try:
        # Color
        try:
            await page.get_by_role("combobox", name="Color").select_option(label="Blue")
        except Exception:
            try:
                await page.get_by_role("checkbox", name="Blue").check()
            except Exception:
                pass

        # Size: try combobox sequential selects then checkbox fallbacks
        try:
            size_cb = page.get_by_role("combobox", name="Size")
            await size_cb.select_option(label="S")
            await asyncio.sleep(0.2)
            await size_cb.select_option(label="M")
        except Exception:
            try:
                await page.get_by_role("checkbox", name="S").check()
            except Exception:
                pass
            try:
                await page.get_by_role("checkbox", name="M").check()
            except Exception:
                pass
    except Exception:
        pass

    # 13) Generate/create and confirm
    await try_click_any(page, "button", ["Next", "Generate", "Create", "Create Products", "Generate Products", "Finish"]) 
    await asyncio.sleep(1.0)
    await try_click_any(page, "button", ["Apply", "OK", "Done", "Finish", "Create"]) 
    await asyncio.sleep(0.8)

    # 14) Final: Save the product (this likely navigates away) - make this the last action
    save_names = ["Save", "Save and Continue Edit", "Save Product"]
    for name in save_names:
        try:
            await page.get_by_role("button", name=name).click()
            return
        except Exception:
            continue

    # fallback save label
    try:
        await page.get_by_role("button", name="Save and Continue").click()
        return
    except Exception:
        return

